import * as schema from "@notify/db/schema";
import { betterAuth } from "better-auth";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";

type RuntimeProcess = {
  env: Record<string, string | undefined>;
};

const runtimeProcess = (globalThis as { process?: RuntimeProcess }).process;
const databaseUrl =
  runtimeProcess?.env.DATABASE_URL ??
  "postgresql://notify_api:notify_local_api@127.0.0.1:54329/notify";
const baseURL = runtimeProcess?.env.BETTER_AUTH_URL ?? "http://127.0.0.1:8080";
const secret =
  runtimeProcess?.env.BETTER_AUTH_SECRET ??
  "notify-local-development-secret-change-before-production";

const client = postgres(databaseUrl, { max: 10 });
const db = drizzle(client, { schema });

export const auth = betterAuth({
  appName: "Notify",
  baseURL,
  secret,
  database: drizzleAdapter(db, {
    provider: "pg",
    schema,
    usePlural: true,
  }),
  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7,
    updateAge: 60 * 60 * 24,
  },
  user: { modelName: "users" },
  session: {
    modelName: "sessions",
    expiresIn: 60 * 60 * 24 * 7,
    updateAge: 60 * 60 * 24,
  },
  account: { modelName: "accounts" },
  verification: { modelName: "verifications" },
  advanced: {
    database: {
      generateId: "uuid",
    },
  },
});
