export function assertLocalResetUrl(databaseUrl: string): void {
  const parsed = new URL(databaseUrl);
  const localHosts = new Set(["127.0.0.1", "localhost", "[::1]"]);
  const databaseName = parsed.pathname.replace(/^\//, "");

