import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";

import { migrationDatabaseUrl } from "./environment.ts";
import { SEED_PRODUCTS } from "./seed-data.ts";
import { fakeOffers, products } from "./schema.ts";

export async function seedDatabase(): Promise<void> {
  const client = postgres(migrationDatabaseUrl(), {
    max: 1,
    onnotice: () => undefined,
  });
  const database = drizzle(client);

  try {
    for (const [index, product] of SEED_PRODUCTS.entries()) {
      const isSuggested = product.suggestedRank !== null;
      const values = {
        slug: product.slug,
        name: product.name,
        imageUrl: null,
        productUrl: `https://www.target.com/p/notify-placeholder-${product.slug}`,
        retailer: "target",
        retailerProductId: `notify-placeholder-${String(index + 1).padStart(2, "0")}`,
        defaultAlertPriceCents: product.defaultAlertPriceCents,
        isActive: true,
        isSuggested,
        suggestedRank: product.suggestedRank,
        pollIntervalSeconds: isSuggested ? 15 : 60,
        confirmObservations: 1,
      };

      await database
        .insert(products)
        .values(values)
        .onConflictDoUpdate({
          target: products.slug,
          set: values,
        });
    }

    const seededProducts = await database
      .select({ id: products.id })
      .from(products)
      .where(
        inArray(
          products.slug,
          SEED_PRODUCTS.map((product) => product.slug),
        ),
      );

    for (const product of seededProducts) {
      await database
        .insert(fakeOffers)
        .values({
          productId: product.id,
          purchasable: false,
          bestPriceCents: null,
        })
        .onConflictDoUpdate({
          target: fakeOffers.productId,
          set: {
            purchasable: false,
            bestPriceCents: null,
          },
        });
    }

    const verificationRows = await database
      .select({ count: products.id })
      .from(products)
      .where(eq(products.retailer, "target"))
      .limit(1);

    if (verificationRows[0] === undefined) {
      throw new Error("Seed verification could not read the products table.");
    }
  } finally {
    await client.end();
  }
}

export async function listSeedProducts(): Promise<
  { slug: string; name: string; defaultAlertPriceCents: number }[]
> {
  const client = postgres(migrationDatabaseUrl(), {
    max: 1,
    onnotice: () => undefined,
  });
  const database = drizzle(client);

  try {
    return await database
      .select({
        slug: products.slug,
        name: products.name,
        defaultAlertPriceCents: products.defaultAlertPriceCents,
      })
      .from(products)
      .where(
        inArray(
          products.slug,
          SEED_PRODUCTS.map((product) => product.slug),
        ),
      )
      .orderBy(products.slug);
  } finally {
    await client.end();
  }
}
