    /^postgres(?:ql)?:\/\/[^/@]+(?::[^/@]*)?@(?:127\.0\.0\.1|localhost|\[::1\])(?::\d+)?\/notify(?:\?.*)?$/;

  if (!localDatabasePattern.test(databaseUrl)) {
