       WHERE table_schema = 'public'
         AND data_type LIKE 'timestamp%'
         AND data_type <> 'timestamp with time zone'
    `;
    expect(nonCompliant).toEqual([]);
  });

  it("keeps schema ownership and role attributes least-privilege", async () => {
