         "notify_api",
         "notify_api",
         "notify_monitor",
       ])})
       ORDER BY rolname
    `;
    expect(roles).toEqual([
      {
        rolname: "notify_api",
        rolsuper: false,
        rolcreatedb: false,
        rolcreaterole: false,
        rolinherit: false,
      },
      {
        rolname: "notify_migrator",
        rolsuper: false,
        rolcreatedb: false,
        rolcreaterole: false,
        rolinherit: false,
      },
      {
        rolname: "notify_monitor",
        rolsuper: false,
        rolcreatedb: false,
        rolcreaterole: false,
        rolinherit: false,
      },
    ]);

    const schemaRows = await migrator<
      { owner: string; api_can_create: boolean; monitor_can_create: boolean }[]
    >`
