    20	export function assertMigrationLedgerIntegrity(
    21	  checkedInMigrations: readonly CheckedInMigration[],
    22	  appliedMigrations: readonly AppliedMigrationRecord[],
    23	): void {
    24	  for (const [index, migration] of checkedInMigrations.entries()) {
    25	    const previousMigration = checkedInMigrations[index - 1];
    26	    if (
    27	      !Number.isSafeInteger(migration.folderMillis) ||
    28	      (previousMigration !== undefined &&
    29	        migration.folderMillis <= previousMigration.folderMillis)
    30	    ) {
    31	      throw new Error(
    32	        `Checked-in migration ledger is not strictly ordered at position ${String(index + 1)}.`,
    33	      );
    34	    }
    35	  }
    36	
    37	  for (const [index, appliedMigration] of appliedMigrations.entries()) {
    38	    const position = index + 1;
    39	    const checkedInMigration = checkedInMigrations[index];
    40	    if (checkedInMigration === undefined) {
    41	      throw new Error(
    42	        `Database migration ledger has an unknown entry at position ${String(position)}.`,
    43	      );
    44	    }
    45	
    46	    const appliedTimestamp = migrationTimestamp(appliedMigration.createdAt, position);
    47	    const checkedInTimestamp = BigInt(checkedInMigration.folderMillis);
    48	    if (
    49	      appliedTimestamp !== checkedInTimestamp ||
    50	      appliedMigration.hash !== checkedInMigration.hash
    51	    ) {
    52	      throw new Error(
    53	        `Applied migration at position ${String(position)} does not match the checked-in immutable ledger.`,
    54	      );
    55	    }
    56	  }
    57	}
