## 6. PostgreSQL database and migrations

PostgreSQL 17 runs in Docker locally and on Neon when hosted. All timestamps are `timestamptz`; all money is integer cents. Enable only `pgcrypto` for `gen_random_uuid()`. Do not depend on Neon-only features.

`packages/db` is server-only. Its Drizzle schema is the TypeScript model for ordinary queries, and `packages/db/migrations` is the one ordered, immutable migration ledger. Generate ordinary migrations with Drizzle Kit; add functions, triggers, role grants, and other PostgreSQL-specific work as custom SQL in the same sequence. Better Auth schema generation updates the checked-in Drizzle schema first; Drizzle Kit then generates the reviewed migration. Neither Better Auth nor Drizzle may migrate a hosted database at application startup.
import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import * as schema from "@notify/db/schema";
import { betterAuth } from "better-auth";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";

type RuntimeProcess = {
  env: Record<string, string | undefined>;
};

const runtimeProcess = (globalThis as { process?: RuntimeProcess }).process;

function requiredEnvironmentVariable(name: string): string {
  const value = runtimeProcess?.env[name];
  if (value === undefined || value.length === 0) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

const databaseUrl = requiredEnvironmentVariable("DATABASE_URL");
const baseURL = requiredEnvironmentVariable("BETTER_AUTH_URL");
const secret = requiredEnvironmentVariable("BETTER_AUTH_SECRET");
if (secret.length < 32) {
  throw new Error("BETTER_AUTH_SECRET must contain at least 32 characters.");
}

const client = postgres(databaseUrl, { max: 10 });
const db = drizzle(client, { schema });

export const auth = betterAuth({
  appName: "Notify",
  baseURL,
  secret,
  database: drizzleAdapter(db, {
    provider: "pg",
    schema,
    usePlural: true,
  }),
  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7,
    updateAge: 60 * 60 * 24,
  },
  advanced: {
    database: {
      generateId: "uuid",
    },
  },
});
import type { MigrationMeta } from "drizzle-orm/migrator";

export type AppliedMigrationRecord = {
  createdAt: bigint | number | string;
  hash: string;
};

type CheckedInMigration = Pick<MigrationMeta, "folderMillis" | "hash">;

function migrationTimestamp(value: bigint | number | string, position: number): bigint {
  try {
    return BigInt(value);
  } catch {
    throw new Error(
      `Database migration ledger has an invalid timestamp at position ${String(position)}.`,
    );
  }
}

export function assertMigrationLedgerIntegrity(
  checkedInMigrations: readonly CheckedInMigration[],
  appliedMigrations: readonly AppliedMigrationRecord[],
): void {
  for (const [index, migration] of checkedInMigrations.entries()) {
    const previousMigration = checkedInMigrations[index - 1];
    if (
      !Number.isSafeInteger(migration.folderMillis) ||
      (previousMigration !== undefined &&
        migration.folderMillis <= previousMigration.folderMillis)
    ) {
      throw new Error(
        `Checked-in migration ledger is not strictly ordered at position ${String(index + 1)}.`,
      );
    }
  }

  for (const [index, appliedMigration] of appliedMigrations.entries()) {
    const position = index + 1;
    const checkedInMigration = checkedInMigrations[index];
    if (checkedInMigration === undefined) {
      throw new Error(
        `Database migration ledger has an unknown entry at position ${String(position)}.`,
      );
    }

    const appliedTimestamp = migrationTimestamp(appliedMigration.createdAt, position);
    const checkedInTimestamp = BigInt(checkedInMigration.folderMillis);
    if (
      appliedTimestamp !== checkedInTimestamp ||
      appliedMigration.hash !== checkedInMigration.hash
    ) {
      throw new Error(
        `Applied migration at position ${String(position)} does not match the checked-in immutable ledger.`,
      );
    }
  }
}
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { readMigrationFiles } from "drizzle-orm/migrator";
import postgres, { type Sql } from "postgres";

import { migrationDatabaseUrl, runtimeProcess } from "./environment.ts";
import {
  type AppliedMigrationRecord,
  assertMigrationLedgerIntegrity,
} from "./migration-integrity.ts";

const migrationsSchema = "public";
const migrationsTable = "__drizzle_migrations";

async function readAppliedMigrations(client: Sql): Promise<AppliedMigrationRecord[]> {
  const tableRows = await client<{ exists: boolean }[]>`
    SELECT to_regclass('public.__drizzle_migrations') IS NOT NULL AS exists
  `;
  if (tableRows[0]?.exists !== true) {
    return [];
  }

  const rows = await client<{ createdAt: string; hash: string }[]>`
    SELECT hash, created_at::text AS "createdAt"
      FROM public.__drizzle_migrations
     ORDER BY id
  `;
  return rows;
}

export async function migrateDatabase(): Promise<void> {
  const migrationsFolder = `${runtimeProcess.cwd()}/migrations`;
  const migrationConfig = {
    migrationsFolder,
    migrationsSchema,
    migrationsTable,
  } as const;
  const checkedInMigrations = readMigrationFiles(migrationConfig);
  const client = postgres(migrationDatabaseUrl(), {
    max: 1,
    onnotice: () => undefined,
  });
  const database = drizzle(client);

  try {
    assertMigrationLedgerIntegrity(
      checkedInMigrations,
      await readAppliedMigrations(client),
    );
    await migrate(database, migrationConfig);

    const appliedMigrations = await readAppliedMigrations(client);
    assertMigrationLedgerIntegrity(checkedInMigrations, appliedMigrations);
    if (appliedMigrations.length !== checkedInMigrations.length) {
      throw new Error("Database migration ledger is incomplete after migration.");
    }
  } finally {
    await client.end();
  }
}
