      RETURNING id
    `;
    const { id: userId } = firstRow(userRows);
    const productRows = await api<{ id: string }[]>`
      SELECT id FROM products ORDER BY slug LIMIT 1
    `;
    const { id: productId } = firstRow(productRows);
    const alertRows = await api<{ id: string }[]>`
