        DELETE FROM realtime_tickets
         WHERE user_id = ${userId}
           AND (expires_at <= now() OR consumed_at IS NOT NULL)
        RETURNING user_id
      `;
      expect(staleRows).toEqual([{ user_id: userId }]);

      await api`
        INSERT INTO realtime_tickets (ticket_hash, user_id, expires_at)
