    expect(() =>
      assertLocalResetUrl("postgresql://notify_migrator:secret@db.example.com/notify"),
    ).toThrow(/local\/test-only/);
    expect(() =>
      assertLocalResetUrl("postgresql://notify_migrator:secret@localhost/customer_data"),
    ).toThrow(/local\/test-only/);
  });
