import postgres from "postgres";

import { MIGRATOR_DEFAULT_PRIVILEGES_RESET_SQL } from "./default-privileges.ts";
import {
  assertLocalResetUrl,
  migrationDatabaseUrl,
  runtimeProcess,
} from "./environment.ts";
import { seedDatabase } from "./seed-operations.ts";

const databaseUrl = migrationDatabaseUrl();
assertLocalResetUrl(databaseUrl);

const client = postgres(databaseUrl, {
  max: 1,
  onnotice: () => undefined,
});

try {
  await client.begin(async (transaction) => {
    await transaction.unsafe(MIGRATOR_DEFAULT_PRIVILEGES_RESET_SQL);
    await transaction.unsafe(
      "CREATE SCHEMA notify_reset_pgcrypto AUTHORIZATION notify_migrator",
    );
    await transaction.unsafe(
      "ALTER EXTENSION pgcrypto SET SCHEMA notify_reset_pgcrypto",
    );
    await transaction.unsafe("DROP SCHEMA IF EXISTS public CASCADE");
    await transaction.unsafe("CREATE SCHEMA public AUTHORIZATION notify_migrator");
    await transaction.unsafe("ALTER EXTENSION pgcrypto SET SCHEMA public");
    await transaction.unsafe("DROP SCHEMA notify_reset_pgcrypto");
  });
} finally {
  await client.end();
}

await seedDatabase();
runtimeProcess.stdout.write("Local Notify database reset, migrated, and seeded.\n");
type RuntimeProcess = {
  cwd: () => string;
  env: Record<string, string | undefined>;
  stdout: { write: (message: string) => void };
};

const candidateProcess = (globalThis as { process?: RuntimeProcess }).process;

export const runtimeProcess: RuntimeProcess = (() => {
  if (candidateProcess === undefined) {
    throw new Error("@notify/db requires a Node.js runtime.");
  }
  return candidateProcess;
})();

export const LOCAL_MIGRATION_URL =
  "postgresql://notify_migrator:notify_local_migrator@127.0.0.1:54329/notify";

export function migrationDatabaseUrl(): string {
  return runtimeProcess.env.DATABASE_MIGRATION_URL ?? LOCAL_MIGRATION_URL;
}

export function assertLocalResetUrl(databaseUrl: string): void {
  const localDatabasePattern =
    /^postgres(?:ql)?:\/\/[^/@]+(?::[^/@]*)?@(?:127\.0\.0\.1|localhost)(?::\d+)?\/notify(?:\?.*)?$/;

  if (!localDatabasePattern.test(databaseUrl)) {
    throw new Error(
      "db:reset is local/test-only and requires the local Notify PostgreSQL database.",
    );
  }
}
