SELECT grantee, table_name, privilege_type, string_agg(column_name, ',' ORDER BY column_name) AS cols
FROM information_schema.column_privileges
WHERE table_schema='public' AND grantee IN ('notify_api','notify_monitor')
GROUP BY grantee, table_name, privilege_type
HAVING count(*) < (SELECT count(*) FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name=table_name)
ORDER BY grantee, table_name, privilege_type;
SELECT t.tablename AS tbl,
  string_agg(DISTINCT CASE WHEN has_table_privilege('notify_api', t.schemaname||'.'||t.tablename, p) THEN p END, ',' ORDER BY CASE WHEN has_table_privilege('notify_api', t.schemaname||'.'||t.tablename, p) THEN p END) AS api,
  string_agg(DISTINCT CASE WHEN has_table_privilege('notify_monitor', t.schemaname||'.'||t.tablename, p) THEN p END, ',' ORDER BY CASE WHEN has_table_privilege('notify_monitor', t.schemaname||'.'||t.tablename, p) THEN p END) AS monitor
FROM pg_tables t
CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) AS p
WHERE t.schemaname='public'
GROUP BY t.tablename ORDER BY t.tablename;
